<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bank Soal — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;font-size:14px}.wrap{max-width:1080px;margin:30px auto;padding:0 20px}.nav{display:flex;gap:10px}.nav a,a{color:#23395d;text-decoration:none;font-weight:700}.hero{margin:18px 0;padding:25px 28px;border-radius:20px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.hero h1{margin:0 0 7px}.hero p{margin:0;color:#e7effa}.card{background:#fffd;border:1px solid #fff;border-radius:17px;padding:22px;margin:18px 0;box-shadow:0 12px 26px #23395d0d}.field{display:grid;gap:6px;margin:11px 0}.field label{font-size:12px;font-weight:800;color:#475569}input,textarea,select{padding:10px;border:1px solid #cbd5e1;border-radius:9px;font:inherit;width:100%}textarea{min-height:72px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.question-card{position:relative;margin:17px 0;padding:17px;border:1px solid #dbe5f0;border-radius:14px;background:#f8fafc}.number{display:inline-grid;place-items:center;width:30px;height:30px;background:#23395d;color:#fff;border-radius:9px;font-weight:800}.remove{position:absolute;right:15px;top:15px;border:0;background:#fee2e2;color:#991b1b;padding:7px 9px;border-radius:8px;font-weight:700;cursor:pointer}.options{display:grid;gap:8px}.option{display:grid;grid-template-columns:35px 1fr auto;gap:7px;align-items:center}.letter{display:grid;place-items:center;height:39px;border-radius:8px;background:#e8eef7;color:#23395d;font-weight:800}.option button{border:0;border-radius:8px;padding:9px;background:#fee2e2;color:#991b1b;cursor:pointer}.button{background:#23395d;color:#fff;border:0;border-radius:9px;padding:10px 14px;font-weight:700;cursor:pointer}.secondary{background:#e8eef7;color:#23395d}.delete{background:#b91c1c}.success{padding:10px;color:#166534;background:#dcfce7;border-radius:9px}.error{color:#b91c1c}.hint{color:#64748b;font-size:12px;line-height:1.6}.example-title{margin:14px 0 7px;color:#23395d;font-size:13px;font-weight:800}.example{white-space:pre-line;padding:13px;background:#172033;color:#e7effa;border-radius:10px;font:12px ui-monospace,monospace;line-height:1.55}.question{padding:14px 0;border-bottom:1px solid #e2e8f0}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><nav class="nav"><a href="{{ route('dashboard') }}">← Dashboard</a><a href="{{ route('teacher.exams') }}">Kelola Ujian</a></nav><section class="hero"><h1>Bank Soal</h1><p>Buat set soal hingga 50 nomor dan atur opsi jawaban sesuai kebutuhan.</p></section>@if(session('success'))<p class="success">✓ {{ session('success') }}</p>@endif @foreach($errors->all() as $error)<p class="error">{{ $error }}</p>@endforeach<section class="card"><h2>Impor Daftar Soal dari PDF</h2><p class="hint">PDF teks dibaca berdasarkan nomor soal. Jumlah opsi bebas (minimal 2), boleh A–B, A–E, dan seterusnya. Baris kunci boleh memakai <b>Kunci Jawaban: B</b>, <b>Kunci: B</b>, atau <b>Jawaban: B</b>.</p><p class="example-title">Contoh soal di PDF</p><div class="example">1. Ibu kota Indonesia adalah?
A. Bandung
B. Jakarta
C. Surabaya
D. Medan
E. Makassar
Kunci Jawaban: B</div><form method="post" action="{{ route('teacher.questions.import-pdf') }}" enctype="multipart/form-data">@csrf<div class="grid"><div class="field"><label>MATA PELAJARAN</label><input name="subject" required></div><div class="field"><label>FILE PDF MAKS. 10 MB</label><input type="file" name="pdf" accept="application/pdf" required></div></div><button class="button">Impor Semua Nomor Soal</button></form></section><section class="card"><h2>Buat Set Soal Manual</h2><p class="hint">Tambahkan atau hapus opsi di setiap soal. Kunci jawaban tiap nomor tidak berubah saat menambah nomor soal baru.</p><form method="post" action="{{ route('teacher.questions.store') }}">@csrf<div class="field"><label>MATA PELAJARAN UNTUK SET INI</label><input name="subject" value="{{ old('subject') }}" placeholder="Contoh: Matematika" required></div><div id="questions"></div><p><button type="button" class="button secondary" id="add-question">+ Tambah Nomor Soal</button> <button class="button">Simpan Semua Soal</button></p></form></section><section class="card"><h2>Daftar Soal ({{ $questions->count() }})</h2>@forelse($questions as $question)<article class="question"><strong>{{ $question->question_text }}</strong><p class="hint">{{ $question->subject }} · Kunci {{ $question->correct_answer }} · Bobot {{ $question->weight }}</p><a class="button" href="{{ route('teacher.questions.edit',$question->id) }}">Ubah</a> <form method="post" action="{{ route('teacher.questions.destroy',$question->id) }}" style="display:inline" onsubmit="return confirm('Hapus soal ini?')">@csrf @method('DELETE')<button class="button delete">Hapus</button></form></article>@empty<p class="hint">Belum ada soal.</p>@endforelse</section></main><template id="question-template"><article class="question-card"><button type="button" class="remove">Hapus soal</button><p><span class="number"></span> <strong>Soal nomor <span class="n"></span></strong></p><div class="field"><label>PERTANYAAN</label><textarea data-field="question_text" required></textarea></div><div class="field"><label>PILIHAN JAWABAN</label><div class="options"></div><button type="button" class="button secondary add-option">+ Tambah Opsi</button></div><div class="grid"><div class="field"><label>JAWABAN BENAR</label><select data-field="correct_answer"></select></div><div class="field"><label>BOBOT NILAI</label><input data-field="weight" type="number" value="20" min="1" max="100" required></div></div></article></template><template id="option-template"><div class="option"><span class="letter"></span><input required><button type="button" title="Hapus opsi">×</button></div></template><script>const list=document.querySelector('#questions'),qTpl=document.querySelector('#question-template'),oTpl=document.querySelector('#option-template'),addQ=document.querySelector('#add-question'),letter=i=>String.fromCharCode(65+i);function syncQuestion(card,index){card.querySelector('.number').textContent=index+1;card.querySelector('.n').textContent=index+1;card.querySelectorAll('[data-field]').forEach(el=>el.name=`questions[${index}][${el.dataset.field}]`);const options=[...card.querySelectorAll('.option')],select=card.querySelector('select'),saved=select.dataset.selected||select.value||'A';select.innerHTML='';options.forEach((row,i)=>{const l=letter(i),input=row.querySelector('input');row.querySelector('.letter').textContent=l;input.name=`questions[${index}][choices][${i}]`;select.add(new Option(l,l));row.querySelector('button').hidden=options.length<=2});select.value=[...select.options].some(o=>o.value===saved)?saved:'A';select.dataset.selected=select.value;select.onchange=()=>{select.dataset.selected=select.value}}function refresh(){[...list.children].forEach(syncQuestion);addQ.disabled=list.children.length>=50}function addOption(card){if(card.querySelectorAll('.option').length>=26)return;const row=oTpl.content.firstElementChild.cloneNode(true);row.querySelector('button').onclick=()=>{row.remove();refresh()};card.querySelector('.options').appendChild(row);refresh()}function addQuestion(){if(list.children.length>=50)return;const card=qTpl.content.firstElementChild.cloneNode(true);card.querySelector('.remove').onclick=()=>{card.remove();refresh()};card.querySelector('.add-option').onclick=()=>addOption(card);list.appendChild(card);addOption(card);addOption(card);refresh()}addQ.onclick=addQuestion;addQuestion()</script></body></html>
